import React from 'react';
import { getAuthToken } from '../../services/authStorage';

export const ExportMenu = ({ exportUrl }) => { const download = (format) => { const baseUrl = exportUrl || '/api/sales/v2/export.csv'; const url = format === 'csv' ? baseUrl : baseUrl.replace('.csv', '.xlsx'); window.open(url, '_blank', 'noopener,noreferrer'); }; const share = () => { const link = window.location.href; window.open(`https://wa.me/?text=${encodeURIComponent(link)}`, '_blank', 'noopener,noreferrer'); }; return <div className="sales-v2-export"><button type="button" onClick={() => download('csv')}>Export CSV</button><button type="button" onClick={() => download('xlsx')}>Export Excel</button><button type="button" onClick={share}>Share</button>{getAuthToken() ? null : <small>Sign in to export</small>}</div>; };
